macro.command:
const mode = args[0];
const types = ["acid", "cold", "fire", "lightning", "thunder"];

if (mode === "activateImmunity") {
  const { effectUuid, type, itemUuid } = args[args.length - 1];
  const effect = await fromUuid(effectUuid);
  const actor = effect?.parent;
  if (!effect?.active || MidiQOL.hasUsedReaction(actor)) return false;

  const changes = effect.toObject().system.changes;
  if (!changes.some(c => c.key === "system.traits.dr.value")) return false;

  const concentration = MidiQOL.getConcentrationEffect(actor, itemUuid);
  const combat = game.combat;
  const inCombat = combat?.started && combat.getCombatantsByActor(actor).length > 0;

  await MidiQOL.setReactionUsed(actor);
  await effect.update({
    "system.changes": [
      ...changes.filter(c => c.key !== "system.traits.dr.value"),
      { key: "system.traits.di.value", value: type, type: "add", phase: "initial" },
      ...(concentration ? [{
        key: "flags.dae.deleteUuid", value: concentration.uuid,
        type: "custom", phase: "initial"
      }] : [])
    ],
    // 从使用反应的这一刻计时，跳过当前回合末。
    start: effect.constructor.getEffectStart(inCombat ? combat : null),
    duration: inCombat
      ? { expiry: "targetEnd", value: null, expired: false }
      : { expiry: null, value: 6, units: "seconds", expired: false }
  });
  return true;
}

if (mode.macroPass !== "preTargetDamageApplication") return;

const { actor } = mode.options;
const damage = workflow.damageItem;
if (!damage?.wasHit || damage.actorUuid !== actor.uuid) return;

const selected = workflow.elementalImmunity ??= new Map();
let type = selected.get(actor.uuid);

if (!type) {
  if (MidiQOL.hasUsedReaction(actor)) return;

  const effect = actor.effects.find(e =>
    e.active &&
    (e.system.origin?.item ?? e.origin) === macroItem.uuid &&
    e.system.changes.some(c => c.key === "system.traits.dr.value")
  );
  if (!effect) return;

  const incoming = types.filter(type => damage.calculatedDamages.some(d =>
    d.type === type && d.value > 0 &&
    !d.active?.absorption && !d.active?.type?.absorption
  ));
  if (!incoming.length) return;

  const dialog = dnd5eClasspack.dialogUtils;
  const userId = dnd5eClasspack.firstOwner(actor, true);
  if (incoming.length === 1) {
    const label = game.i18n.localize(CONFIG.DND5E.damageTypes[incoming[0]].label);
    if (!await dialog.confirm(macroItem.name, `使用反应获得${label}伤害免疫？`, { userId })) return;
    type = incoming[0];
  } else {
    type = await dialog.selectDamageType(
      incoming, macroItem.name, "使用反应，选择要免疫的伤害类型。",
      { addNo: true, userId }
    );
    if (!type) return;
  }

  const applied = await socketlib.modules.get("dae").executeAsGM("executeMacro", {
    action: "activateImmunity",
    lastArg: { effectUuid: effect.uuid, type, itemUuid: macroItem.uuid },
    macroData: { change: { key: "macro.itemMacro" }, name: macroItem.uuid }
  });
  if (!applied) return;
  selected.set(actor.uuid, type);
}

// 每条 Midi 伤害记录已经按伤害分组，用这条记录的原始伤害重算。
const settings = MidiQOL.configSettings();
const raw = damage.damages.map(d => ({
  ...d, value: d.type === type ? 0 : d.value, properties: new Set(d.properties)
}));
const buckets = settings.singleDamageCalculation ? [raw]
  : [...new Set(raw.map(d => d.midiCategory))].map(category => raw.filter(d => d.midiCategory === category));
const result = buckets.flatMap(entries => {
  const options = foundry.utils.deepClone(damage.options);
  if (options.downgrade instanceof Set) options.downgrade = new Set(options.downgrade);
  if (options.ignore && options.ignore !== true) {
    for (const [key, value] of Object.entries(options.ignore)) {
      if (value instanceof Set) options.ignore[key] = new Set(value);
    }
  }
  return actor.calculateDamage(entries, options) || [];
});

const hp = actor.system.attributes.hp;
const sum = result.reduce((s, d) => {
  if (d.type === "temphp") s.temp += d.value;
  else if (d.type === "maximum") s.tempMax += d.value;
  else if (d.type === "healing" || d.active?.absorption || d.active?.type?.absorption) s.heal += d.value;
  else if (!["midi-none", "vitality"].includes(d.type)) s.damage += d.value;
  return s;
}, { temp: 0, tempMax: 0, heal: 0, damage: 0 });

const total = Math.trunc(Math.max(0, sum.damage) + sum.heal);
const tempUsed = Math.min(hp.temp, Math.max(0, total));
const hpDamage = Math.clamp(total - tempUsed, -hp.damage + sum.tempMax, hp.value - sum.tempMax);
const newTempHP = Math.max(hp.temp - tempUsed, sum.temp);

Object.assign(damage, {
  calculatedDamages: result,
  totalDamage: Math.max(0, sum.damage),
  hpDamage,
  newHP: hp.value - hpDamage,
  newTempHP,
  tempDamage: hp.temp - newTempHP
});
